  @override
  Widget build(BuildContext context) => Scaffold(body: Center(child: Padding(padding: const EdgeInsets.all(32), child: Column(mainAxisSize: MainAxisSize.min, children: [const Icon(Icons.menu_book_rounded, size: 48), const SizedBox(height: 16), Text('Welcome to Coursewise', style: Theme.of(context).textTheme.headlineMedium, textAlign: TextAlign.center), const SizedBox(height: 12), const Text('Enable Firebase Authentication with Email/Password to activate student sign-in.'), const SizedBox(height: 24), FilledButton(onPressed: () {}, child: const Text('Sign in after Firebase setup'))])));
