class StudentScaffold extends StatelessWidget {
  const StudentScaffold({required this.title, required this.child, super.key});
  final String title;
  final Widget child;
  @override
  Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: Text(title, style: Theme.of(context).textTheme.titleLarge), actions: [IconButton(onPressed: () => context.go('/profile'), icon: const Icon(Icons.account_circle_outlined))]), body: SafeArea(child: child), bottomNavigationBar: NavigationBar(selectedIndex: _index(context), onDestinationSelected: (index) => context.go(['/home', '/lessons', '/quizzes', '/profile'][index]), destinations: const [NavigationDestination(icon: Icon(Icons.home_outlined), selectedIcon: Icon(Icons.home), label: 'Home'), NavigationDestination(icon: Icon(Icons.menu_book_outlined), selectedIcon: Icon(Icons.menu_book), label: 'Lessons'), NavigationDestination(icon: Icon(Icons.fact_check_outlined), selectedIcon: Icon(Icons.fact_check), label: 'Quizzes'), NavigationDestination(icon: Icon(Icons.person_outline), selectedIcon: Icon(Icons.person), label: 'Profile')]));
  int _index(BuildContext context) { final path = GoRouterState.of(context).uri.path; if (path.startsWith('/lessons')) return 1; if (path.startsWith('/quizzes')) return 2; if (path.startsWith('/profile')) return 3; return 0; }
}

class HomeScreen extends ConsumerWidget {
  const HomeScreen({super.key});
  @override
  Widget build(BuildContext context, WidgetRef ref) { final profile = ref.watch(profileProvider); final announcements = ref.watch(announcementsProvider); return StudentScaffold(title: 'Coursewise', child: ListView(padding: const EdgeInsets.all(20), children: [profile.when(data: (value) => _WelcomeCard(name: value?.name ?? 'Learner', studentId: value?.studentId ?? 'Student ID pending'), loading: _loading, error: (_, __) => const _WelcomeCard(name: 'Learner', studentId: 'Connect Firebase to load profile')), const SizedBox(height: 24), Text('Announcements', style: Theme.of(context).textTheme.titleLarge), const SizedBox(height: 10), announcements.when(data: (items) => items.isEmpty ? const EmptyNotice(title: 'No announcements available') : AnnouncementCarousel(items: items), loading: _loading, error: (_, __) => const EmptyNotice(title: 'Announcements will appear here')), const SizedBox(height: 24), Text('Your learning space', style: Theme.of(context).textTheme.titleLarge), const SizedBox(height: 10), GridView.count(crossAxisCount: 2, childAspectRatio: 1.28, shrinkWrap: true, physics: const NeverScrollableScrollPhysics(), mainAxisSpacing: 12, crossAxisSpacing: 12, children: [QuickTile(icon: Icons.menu_book_outlined, title: 'Lessons', subtitle: 'Resource library', onTap: () => context.go('/lessons')), QuickTile(icon: Icons.fact_check_outlined, title: 'Quizzes', subtitle: 'Check understanding', onTap: () => context.go('/quizzes')), QuickTile(icon: Icons.assignment_outlined, title: 'Assignments', subtitle: 'View what is next', onTap: () => context.go('/assignments')), QuickTile(icon: Icons.calendar_month_outlined, title: 'Attendance', subtitle: 'Review your record', onTap: () => context.go('/attendance'))]) ])); }
}

class LessonsScreen extends ConsumerWidget { const LessonsScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref) { final lessons = ref.watch(lessonsProvider); return StudentScaffold(title: 'Lessons', child: lessons.when(data: (items) => items.isEmpty ? const EmptyNotice(title: 'No lessons available') : ListView.separated(padding: const EdgeInsets.all(20), itemCount: items.length, separatorBuilder: (_, __) => const SizedBox(height: 12), itemBuilder: (_, index) => LessonCard(lesson: items[index])), loading: _loading, error: (_, __) => const EmptyNotice(title: 'Lessons will appear here')); } }

class QuizzesScreen extends ConsumerWidget { const QuizzesScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref) { final quizzes = ref.watch(quizzesProvider); return StudentScaffold(title: 'Quizzes', child: quizzes.when(data: (items) => items.isEmpty ? const EmptyNotice(title: 'No quizzes available') : ListView.separated(padding: const EdgeInsets.all(20), itemCount: items.length, separatorBuilder: (_, __) => const SizedBox(height: 12), itemBuilder: (_, index) => Card(child: ListTile(contentPadding: const EdgeInsets.all(18), leading: const CircleAvatar(child: Icon(Icons.fact_check_outlined)), title: Text(items[index].title), subtitle: Text('${items[index].totalMarks} marks${items[index].durationMinutes == null ? '' : ' · ${items[index].durationMinutes} min'}'), trailing: FilledButton(onPressed: () {}, child: const Text('Start')))), loading: _loading, error: (_, __) => const EmptyNotice(title: 'Quizzes will appear here')); } }

class AttendanceScreen extends ConsumerWidget { const AttendanceScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref) { final attendance = ref.watch(attendanceProvider); return StudentScaffold(title: 'Attendance', child: attendance.when(data: (items) { final present = items.where((item) => item.status == 'Present' || item.status == 'Late').length; final rate = items.isEmpty ? 0 : (present / items.length * 100).round(); return ListView(padding: const EdgeInsets.all(20), children: [Card(color: const Color(0xFF143D36), child: Padding(padding: const EdgeInsets.all(24), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('Attendance rate', style: TextStyle(color: Color(0xFFD4F59B))), const SizedBox(height: 8), Text('$rate%', style: Theme.of(context).textTheme.headlineMedium?.copyWith(color: Colors.white)), const SizedBox(height: 14), LinearProgressIndicator(value: rate / 100, color: const Color(0xFFD4F59B), backgroundColor: Colors.white24)])), const SizedBox(height: 20), if (items.isEmpty) const EmptyNotice(title: 'No attendance records yet') else ...items.map((item) => Card(child: ListTile(title: Text(item.date), subtitle: Text(item.note ?? 'No note'), trailing: StatusChip(status: item.status))))]); }, loading: _loading, error: (_, __) => const EmptyNotice(title: 'Attendance will appear here')); } }

class AssignmentsScreen extends StatelessWidget { const AssignmentsScreen({super.key}); @override Widget build(BuildContext context) => const StudentScaffold(title: 'Assignments', child: Center(child: EmptyNotice(title: 'No assignments available'))); }

class ProfileScreen extends ConsumerWidget { const ProfileScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref) { final profile = ref.watch(profileProvider); return StudentScaffold(title: 'Profile', child: profile.when(data: (value) => ListView(padding: const EdgeInsets.all(20), children: [Card(child: Padding(padding: const EdgeInsets.all(24), child: Column(children: [CircleAvatar(radius: 36, backgroundImage: value?.photoUrl == null ? null : NetworkImage(value!.photoUrl!), child: value?.photoUrl == null ? Text((value?.name ?? 'S').substring(0, 1)) : null), const SizedBox(height: 16), Text(value?.name ?? 'Student', style: Theme.of(context).textTheme.titleLarge), Text(value?.email ?? ''), const SizedBox(height: 18), ListTile(leading: const Icon(Icons.badge_outlined), title: const Text('Student ID'), subtitle: Text(value?.studentId ?? 'Not assigned')), const Divider(), ListTile(leading: const Icon(Icons.logout), title: const Text('Sign out'), onTap: () => ref.read(studentRepositoryProvider).signOut())]))]), loading: _loading, error: (_, __) => const EmptyNotice(title: 'Profile will appear here')); } }

class _WelcomeCard extends StatelessWidget { const _WelcomeCard({required this.name, required this.studentId}); final String name; final String studentId; @override Widget build(BuildContext context) => Card(color: const Color(0xFF143D36), child: Padding(padding: const EdgeInsets.all(24), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('STUDENT HOME', style: TextStyle(color: Color(0xFFD4F59B), fontSize: 11, letterSpacing: 1.5)), const SizedBox(height: 12), Text('Hello, $name.', style: Theme.of(context).textTheme.headlineMedium?.copyWith(color: Colors.white)), const SizedBox(height: 6), Text('Student ID · $studentId', style: const TextStyle(color: Color(0xFFD4F59B)))]))); }
class AnnouncementCarousel extends StatelessWidget { const AnnouncementCarousel({required this.items, super.key}); final List<Announcement> items; @override Widget build(BuildContext context) => SizedBox(height: 180, child: PageView.builder(itemCount: items.length, itemBuilder: (_, index) => Card(clipBehavior: Clip.antiAlias, child: Stack(fit: StackFit.expand, children: [if (items[index].imageUrl != null) Image.network(items[index].imageUrl!, fit: BoxFit.cover), Container(color: const Color(0xCC143D36)), Padding(padding: const EdgeInsets.all(20), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Spacer(), Text(items[index].title, style: Theme.of(context).textTheme.titleLarge?.copyWith(color: Colors.white)), if (items[index].description != null) Text(items[index].description!, style: const TextStyle(color: Colors.white70))]))]))); }
class LessonCard extends StatelessWidget { const LessonCard({required this.lesson, super.key}); final Lesson lesson; @override Widget build(BuildContext context) => Card(child: Padding(padding: const EdgeInsets.all(18), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(lesson.title, style: Theme.of(context).textTheme.titleMedium), if (lesson.description != null) Padding(padding: const EdgeInsets.only(top: 6), child: Text(lesson.description!)), const SizedBox(height: 14), Wrap(spacing: 8, runSpacing: 8, children: [if (lesson.videoUrl != null) ResourceButton(label: 'Video', url: lesson.videoUrl!), if (lesson.pdfUrl != null) ResourceButton(label: 'PDF', url: lesson.pdfUrl!), if (lesson.telegramUrl != null) ResourceButton(label: 'Telegram', url: lesson.telegramUrl!)])]))); }
class ResourceButton extends StatelessWidget { const ResourceButton({required this.label, required this.url, super.key}); final String label; final String url; @override Widget build(BuildContext context) => OutlinedButton(onPressed: () => launchUrl(Uri.parse(url), mode: LaunchMode.externalApplication), child: Text(label)); }
class QuickTile extends StatelessWidget { const QuickTile({required this.icon, required this.title, required this.subtitle, required this.onTap, super.key}); final IconData icon; final String title; final String subtitle; final VoidCallback onTap; @override Widget build(BuildContext context) => Card(child: InkWell(onTap: onTap, borderRadius: BorderRadius.circular(24), child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Icon(icon, color: const Color(0xFF143D36)), const Spacer(), Text(title, style: Theme.of(context).textTheme.titleMedium), Text(subtitle, style: Theme.of(context).textTheme.bodySmall)])))); }
class StatusChip extends StatelessWidget { const StatusChip({required this.status, super.key}); final String status; @override Widget build(BuildContext context) { final colors = {'Present': Colors.green, 'Absent': Colors.red, 'Late': Colors.orange, 'Excused': Colors.blue}; return Chip(label: Text(status), backgroundColor: colors[status]?.withValues(alpha: .12), side: BorderSide.none); } }
